import{_ as a,c as e,o as t,ah as s}from"./chunks/framework.Dnh4IO1K.js";const h=JSON.parse('{"title":"剝","description":"东坡易传 - 剝","frontmatter":{"title":"剝","description":"东坡易传 - 剝"},"headers":[],"relativePath":"zh/classics/dongpo/024.md","filePath":"zh/classics/dongpo/024.md"}'),o={name:"zh/classics/dongpo/024.md"};function r(n,p,c,_,i,d){return t(),e("div",null,[...p[0]||(p[0]=[s('<h1 id="剝" tabindex="-1">剝 <a class="header-anchor" href="#剝" aria-label="Permalink to “剝”">​</a></h1><p>“剝”：不利有攸往。</p><p>《彖》曰：“剝”，剝也，柔變剛也。“不利有攸往”，小人長也。順而止之，觀象也。君子尚消息盈虛，天行也。</p><p>見可而後動。</p><p>象曰：山附於地，“剝”；上以厚下安宅。</p><p>身安而民與之，則“剝”者自衰，不與之校也。</p><p>初六：剝牀以足，蔑；貞兇。象曰：“剝牀以足”，以滅下也。</p><p>六二：剝牀以辨，蔑；貞兇。象曰：“剝牀以辨”，未有與也。</p><p>陽在上，故君子以上三爻爲己。載己者①，牀也，故下爲牀②。陰之長，猶水之溢也，故曰“蔑”。“辨”，足之上也，牀與足之間，故曰“辨”。君子之於小人，不疾其有邱山之惡，而幸其有毫髮之善，“剝牀以足”，且及其“辨”矣，猶未直以爲兇也，曰“蔑，貞”而後“兇”。小人之於正也，絕蔑無餘，而後“兇”可必也；若猶有餘，則君子自其“餘”而懷之矣，故曰“剝牀以辨，未有與也”。小人之爲惡也，有人與之然後自信以果。方其未有與也，則其愧而未果之際也。</p><p>【校注】 ① 爲己，載己：原文與《蘇氏易傳》均作“已”，均屬刻印之誤。 ② 下爲牀：《蘇氏易傳》作“下爲剝牀”，誤。</p><p>六三：剝之，無咎。象曰：“剝之無咎”，失上下也。</p><p>王弼曰：“羣陰剝陽，己獨協焉①，雖處於剝，可以無咎。”“上下各有二陰，應陽則失上下也。”</p><p>【校注】 ①己獨協焉：原文與《蘇氏易傳》均作“已獨協焉”，均屬刻印之誤。《周易正義》所載王弼原注爲“我獨協焉”，從而改之。</p><p>六四：剝牀以膚，兇。象曰：“剝牀以膚”，切近災也。</p><p>“剝牀以膚”，始及己矣①，雖欲懷之而不可得矣，故直曰“兇”。</p><p>【校注】 ① 始及己矣：原文與《蘇氏易傳》均作“已”，均屬刻印之誤。</p><p>六五：貫魚，以宮人寵，無不利。象曰：“以宮人寵”，終無尤也。</p><p>“觀”之世幾於“剝”矣，而言不及小人者，其主陽也；六五，“剝”之主，凡“剝”者，皆其類也。聖人不能使之無寵於其類，故擇其害之淺者許之。四以下，“貫魚”之象也。自上及下，施寵均也。夫寵均，則勢分；勢分，則害淺矣。以宮人之寵寵之，不及以政也。不及以政，豈惟自安，亦以安之，故“無不利”。聖人之教人也，容其或有而去其太甚，庶幾從之。如責之以必無，則彼有不從而已矣。</p><p>上九：碩果不食，君子得輿，小人剝廬。象曰：“君子得輿”，民所載也；“小人剝廬”，終不可用也。</p><p>“果”，未有不見食者也；“碩”而不見食，必不可食者也。智者去之，愚者眷焉。上九之失民久矣，五陰之勢足以轢而取之，然且獨存於上者，彼特存我以爲名爾，與之合則存，不與之合則亡，君子以爲是不可食之果也，而亟去之。彼得志於上，必食其下，故君子去其上而出其下，可以得民。載於下謂之“輿”，庇於上謂之“廬”。“廬”者，既剝之餘也，豈可複用哉！</p>',20)])])}const m=a(o,[["render",r]]);export{h as __pageData,m as default};
